// nppiConvert family executor (nppiConvert_<src><dst>_<layout>R[_Ctx]).
//
// Host-visible surface (safe for plain .cpp translation units): the entry-point
// templates are declared here and defined + explicitly instantiated in
// nppi_convert_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_convert.json).
//
// Semantics (baseline NVIDIA NPP 13.4, validated by differential tests):
//   * plain   : dst = convert(src);  integer dests saturate (no wrap).
//   * convertRnd  : dst = round(src, eRoundMode) then convert (float/int dest).
//   * convertRndSfs: dst = round(src / 2^sf, eRoundMode) then saturate (int dst).
//   * 2D ROI writes only within oSizeROI; row-tail padding is preserved by
//     the caller, so we never write past the ROI width.
//   * AC4 (AlphaPreserve=true) converts the first three channels and leaves
//     the alpha (4th) channel untouched.
#ifndef NPPI_CONVERT_EXECUTOR_H
#define NPPI_CONVERT_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace convert {

// dst = convert(src); integer dest saturates, float dest casts directly.
template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus convert(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI, cudaStream_t stream);

// dst = round(src, eRoundMode) converted/saturated (float or int destination).
template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus convertRnd(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI, NppRoundMode eRoundMode,
                     cudaStream_t stream);

// dst = round(src / 2^sf, eRoundMode) saturated to an integer destination.
template <typename Src, typename Dst, int Channels, bool AlphaPreserve>
NppStatus convertRndSfs(const Src *pSrc, int nSrcStep, Dst *pDst, int nDstStep, NppiSize oSizeROI,
                        NppRoundMode eRoundMode, int nScaleFactor, cudaStream_t stream);

}  // namespace convert
}  // namespace nppi

#endif  // NPPI_DECI_EXECUTOR_H
